14	
15	/// One side of a dual-repo workspace.
16	///
17	/// - `Work`: the primary work repo.
18	/// - `Bot`: the bot repo (typically at `.claude/`).
19	#[derive(Copy, Clone, Debug, PartialEq, Eq, ValueEnum)]
20	pub enum Side {
21	    Work,
22	    Bot,
23	}
24	
25	/// Parsed `--scope` value: the requested role set of a
26	/// dual-repo workspace.
27	///
28	/// Newtype over `Vec<Side>`. The vector preserves the order the
29	/// keywords were given in (`work,agent` vs `agent,work`).
30	#[derive(Clone, Debug, PartialEq, Eq)]
31	pub struct Scope(pub Vec<Side>);
32	
33	/// Parse a `--scope` value string.
34	///
35	/// Accepts the role-keyword forms (`work`, `agent`, `both`, and
36	/// the spelled-out `work,agent` / `agent,work`) preserving order,
37	/// `both` being `work,agent`. Anything else (an
38	/// empty string, a bare name, duplicate or out-of-set
39	/// combinations, a path) is an error: path-based single-repo
40	/// operation uses `-R/--repo`, not `--scope`.
41	pub fn parse_scope(s: &str) -> Result<Scope, String> {
42	    match s {
43	        "work" => Ok(Scope(vec![Side::Work])),
44	        "agent" => Ok(Scope(vec![Side::Bot])),
45	        "both" | "work,agent" => Ok(Scope(vec![Side::Work, Side::Bot])),
46	        "agent,work" => Ok(Scope(vec![Side::Bot, Side::Work])),
47	        "" => Err("--scope: value is empty".into()),
48	        "bot" | "work,bot" | "bot,work" => Err(format!(
