    if at.side != Side::Work {
        return Ok(());
    }
    let (ws, repo) = common::load_repo(&at.repo)?;
    let wc_id = repo.view().get_wc_commit_id(ws.workspace_name()).cloned();
    let start = match &params.rev {
        Some(rev) => one_commit(&ws, &repo, rev)?,
